const D = (h, ...d) => ({ h, d });
// Fișa unui caz (sau a două cazuri): rows = rândurile din dreapta, script = secțiunile din stânga, în aceeași ordine (un beat pe rând).
// c = { h, e (enunțul scurt, dreapta), en (enunțul, stânga), items: [{ l, q, n: [noțiuni], p, tx }] }
const CASES = (cs, o = {}) => {
  const rows = [], script = [];
  cs.forEach((c) => {
    rows.push({ h: c.h, e: c.e }); script.push({ tm: c.h.split(' · ')[0], at: 'enunțul', tx: c.en });
    c.items.forEach((it) => { rows.push({ l: it.l, q: it.q, n: it.n, p: it.p }); script.push({ tm: it.l, at: it.q + (it.p ? ` (${it.p})` : ''), tx: it.tx }); });
  });
  return { scene: 'fisaR', layout: 'script', anim: false, beatDur: 8,
    spec: 'Static: fișa OSPE a ' + (cs.length > 1 ? 'celor două cazuri' : 'cazului') + ': antetul maro cu enunțul pe scurt, apoi subpunctele (litera, întrebarea, punctajul oficial unde există) cu noțiunile de barem ca pastile verzi, în ordinea în care le spui; rândul activ se aprinde galben, cele trecute primesc ✓.',
    sceneOpts: { rows }, script, ...o };
};
const TABLE = (o, items, head, rows) => ({ scene: 'cards', layout: 'script', anim: false, beatDur: 5,
  spec: `Static (coloana îngustă): ${items.length} carduri = rândurile tabelului (tema + răspunsul-cheie); cardul rândului se aprinde.`,
  sceneOpts: { cols: 2, narrow: true, items }, table: { head, rows }, ...o });

